module TopModule(input a, input b, input cin, output cout, output sum);
    wire w1, w2, w3;
    // First stage: sum of two bits
    assign w1 = a ^ b;
    // Second stage: sum of first sum and carry-in
    assign w2 = w1 ^ cin;
    // Carry-out is the AND of the two first sums, plus the AND of the first
    // sum and the carry-in
    assign w3 = (a & b) | (a & cin) | (b & cin);
    assign sum = w2;
    assign cout = w3;
endmodule

